/**
 * What the runtime knows about this project's entities.
 */
final readonly class Catalogue implements EntityCatalogue
{
    public function __construct(
        private ContainerInterface $container,
    ) {

    }

    /**
     * @return list<string>
     */
    public function entities(): array {
        return ['PointsTransaction', 'User'];
    }

    /**
     * @return Hydrator<object>
     */
    public function hydrator(
        string $entity,
    ): Hydrator {
        $service = match ($entity) {
            'PointsTransaction' => $this->container->get(PointsTransactionHydrator::class),
            'User' => $this->container->get(UserHydrator::class),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };

        assert($service instanceof Hydrator);

        return $service;
    }

    public function verifiers(
        string $entity,
    ): EntityVerifiers {
        $service = match ($entity) {
            'PointsTransaction' => $this->container->get(PointsTransactionVerifiers::class),
            'User' => $this->container->get(UserVerifiers::class),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };

        assert($service instanceof EntityVerifiers);

        return $service;
    }

    public function sideEffects(
        string $entity,
    ): EntitySideEffects {
        $service = match ($entity) {
            'PointsTransaction' => $this->container->get(PointsTransactionSideEffects::class),
            'User' => $this->container->get(UserSideEffects::class),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };

        assert($service instanceof EntitySideEffects);

        return $service;
    }

    public function readPolicies(
        string $entity,
    ): EntityReadPolicies {
        return match ($entity) {
            'PointsTransaction' => new NoPolicies(),
            'User' => new NoPolicies(),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };
    }

    public function writePolicies(
        string $entity,
    ): EntityWritePolicies {
        return match ($entity) {
            'PointsTransaction' => new NoPolicies(),
            'User' => new NoPolicies(),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };
    }

    /**
     * @return array<string, string> "Entity.edge" => target entity
     */
    public function edgeTargets(): array {
        return [
            'PointsTransaction.reference' => 'User',
            'PointsTransaction.user' => 'User',
        ];
    }

    /**
     * @return array<string, string> "Entity.field" => declared type
     */
    public function fieldTypes(): array {
        return [];
    }

    /**
     * @return list<string>
     */
    public function fieldNames(
        string $entity,
    ): array {
        return match ($entity) {
            'PointsTransaction' => ['value'],
            'User' => ['name'],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function requiredFields(
        string $entity,
    ): array {
        return match ($entity) {
            'PointsTransaction' => [],
            'User' => [],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function nonNullableFields(
        string $entity,
    ): array {
        return match ($entity) {
            'PointsTransaction' => ['value'],
            'User' => ['name'],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function requiredEdges(
        string $entity,
    ): array {
        return match ($entity) {
            'PointsTransaction' => ['user'],
            'User' => [],
            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function uniqueFields(
        string $entity,
    ): array {
        return match ($entity) {
            'PointsTransaction' => [],
            'User' => [],
            default => [],
        };
    }

    /**
     * @return array<string, Managed> "Entity.field" => policy
     */
    public function managedFields(): array {
        return [];
    }

    /**
     * @return list<DeletionRule>
     */
    public function deletionRules(
        string $entity,
    ): array {
        return match ($entity) {
            'PointsTransaction' => PointsTransactionDeleter::rules(),
            'User' => UserDeleter::rules(),
            default => [],
        };
    }

    public function finder(
        string $entity,
    ): object {
        $finder = match ($entity) {

            default => throw new RuntimeException(sprintf('%s declares no queries.', $entity)),
        };

        assert(is_object($finder));

        return $finder;
    }

    public function mutatorFor(
        string $entity,
        MutationBuffer $buffer,
    ): object {
        return match ($entity) {
            'PointsTransaction' => new PointsTransactionMutator($buffer),
            'User' => new UserMutator($buffer),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };
    }

    /**
     * @return list<string>
     */
    public function queryArguments(
        string $entity,
        string $query,
    ): array {
        return match ($entity . '.' . $query) {

            default => [],
        };
    }

    /**
     * @return list<string>
     */
    public function actionArguments(
        string $entity,
        string $action,
    ): array {
        return match ($entity . '.' . $action) {

            default => [],
        };
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    private function decodePointsTransactionInputActionArguments(
        string $action,
        array $args,
    ): array {
        $input = $this->container->get(PointsTransactionInput::class);

        assert($input instanceof PointsTransactionInput);

        return $input->decodeAction($action, $args);
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    private function decodeUserInputActionArguments(
        string $action,
        array $args,
    ): array {
        $input = $this->container->get(UserInput::class);

        assert($input instanceof UserInput);

        return $input->decodeAction($action, $args);
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    public function decodeActionArguments(
        string $entity,
        string $action,
        array $args,
    ): array {
        return match ($entity) {
            'PointsTransaction' => $this->decodePointsTransactionInputActionArguments($action, $args),
            'User' => $this->decodeUserInputActionArguments($action, $args),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };
    }

    /**
     * @param array<string, mixed> $input
     */
    public function apply(
        string $entity,
        MutationBuffer $buffer,
        array $input,
    ): void {
        $applier = match ($entity) {
            'PointsTransaction' => $this->container->get(PointsTransactionInput::class),
            'User' => $this->container->get(UserInput::class),
            default => throw new RuntimeException(sprintf('No entity named "%s".', $entity)),
        };

        assert(is_object($applier) && method_exists($applier, 'apply'));

        $applier->apply($buffer, $input);
    }

    /**
     * Everything the application must implement before it can start.
     *
     * @return list<string>
     */
    public function contracts(): array {
        return [];
    }
}

