namespace App\Elephentity\PointsTransaction;

use Eleph\Runtime\Identity\Identifier;
use Eleph\Runtime\Mutation\MutationBuffer;
use Eleph\Runtime\Query\ValueDecoder;
use InvalidArgumentException;

/**
 * Turns raw input into pending PointsTransaction changes.
 */
final readonly class PointsTransactionInput
{
    public function __construct(
        private ValueDecoder $decode,
    ) {

    }

    private function value(
        mixed $value,
    ): ?int {
        if (null === $value) {
            return null;
        }

        return $this->decode->int($value, 'PointsTransaction.value');
    }

    /**
     * @return list<Identifier>
     */
    private function user(
        mixed $value,
    ): array {
        if (null === $value) {
            return [];
        }

        return [$this->decode->id($value, 'PointsTransaction.user')];
    }

    /**
     * @return list<Identifier>
     */
    private function reference(
        mixed $value,
    ): array {
        if (null === $value) {
            return [];
        }

        return [$this->decode->id($value, 'PointsTransaction.reference')];
    }

    /**
     * Seeds declared defaults on create and applies explicit input.
     * Absent update keys and existing pending values are not reset by defaults.
     *
     * @param array<string, mixed> $input
     */
    public function apply(
        MutationBuffer $buffer,
        array $input,
    ): void {
        if (array_key_exists('value', $input)) {
            $buffer->set('value', $this->value($input['value']));
        }

        if (array_key_exists('user', $input)) {
            $buffer->edge('user')->set($this->user($input['user']));
        }

        if (array_key_exists('reference', $input)) {
            $buffer->edge('reference')->set($this->reference($input['reference']));
        }
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    public function decodeAction(
        string $action,
        array $args,
    ): array {
        return match ($action) {

            default => throw new InvalidArgumentException(sprintf('Unknown action %s.', $action)),
        };
    }
}

