/**
 * Pending changes to a PointsTransaction.
 */
final class PointsTransactionMutator
{
    public function __construct(
        private readonly MutationBuffer $buffer,
    ) {

    }

    public function setValue(
        int $value,
    ): self {
        $this->buffer->set('value', $value);

        return $this;
    }

    /**
     * Point this at one User, or at nothing.
     */
    public function setUser(
        ?Identifier $user,
    ): self {
        $this->buffer->edge('user')->set(null === $user ? [] : [$user]);

        return $this;
    }

    /**
     * Point this at one User, or at nothing.
     */
    public function setReference(
        ?Identifier $reference,
    ): self {
        $this->buffer->edge('reference')->set(null === $reference ? [] : [$reference]);

        return $this;
    }
}

